/** Sunday-tone hymn cycle: keyed by resurrectional tone (1..8). Covers
 *  the Octoechos resurrectional troparia and kontakia sung every Sunday
 *  of the week on that tone. */
export const SUNDAY_TONE_HYMNS_CYCLE: ReadonlyMap<number, { readonly troparia: readonly Hymn[]; readonly kontakia: readonly Hymn[] }> = new Map([
	[1, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone I", text: "When Gabriel announced to Thee, O Virgin, “Rejoice!” / with that word the Master of all was incarnate in Thee, O Holy Ark. / As the righteous David said, / Thy womb became more spacious than the heavens, bearing Thy Creator. / Glory to Him Who took abode in Thee! / Glory to Him Who came from Thee! / Glory to Him Who freed us by being born of Thee!", group: 1, saints: [] },
		{ title: "Troparion of the Sunday, Tone I", text: "When the stone had been sealed by the Jews; / while the soldiers were guarding Thy most pure Body; / Thou didst rise on the third day, O Savior, / granting life to the world. / The powers of heaven therefore cried to Thee, O Giver of Life: / Glory to Thy Resurrection, O Christ! / Glory to Thy Kingdom! / Glory to Thy dispensation, O Thou Who lovest mankind.", group: 1, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone I", text: "As God, Thou didst rise from the tomb in glory, / raising the world with Thyself. / Human nature praises Thee as God, for death has vanished! / Adam exults, O Master! / Eve rejoices, for she is freed from bondage, and cries to Thee: / Thou art the Giver of Resurrection to all, O Christ!", group: 1, saints: [] },
		],
	}],
	[2, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone II", text: "All beyond thought, all most glorious, / are your mysteries, O Theotokos. / Sealed in purity, preserved in virginity, / you were revealed to be the true Mother who gave birth to the true God. / Entreat Him to save our souls.", group: 1, saints: [] },
		{ title: "Troparion of the Sunday, Tone II", text: "When Thou didst descend to death, O Life immortal, / Thou didst slay hell with the splendor of Thy Godhead! / And when from the depths Thou didst raise the dead, / all the powers of heaven cried out: / O Giver of life, Christ our God, glory to Thee!", group: 1, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone II", text: "Hell became afraid, O Almighty Savior, / seeing the miracle of Thy Resurrection from the tomb! / The dead arose! Creation, with Adam, beheld this and rejoiced with Thee! / And the world, O my Savior, praises Thee forever.", group: 1, saints: [] },
		],
	}],
	[3, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone III", text: "We praise you as the mediatrix of our salvation, / O Virgin Theotokos. / For your Son, our God, Who took flesh from you, / accepted the passion of the cross, / delivering us from corruption as the Lover of man.", group: 0, saints: [] },
		{ title: "Troparion of the Sunday, Tone III", text: "Let the heavens rejoice, / let the earth be glad! / For the Lord has shown might with His arm,/ He has trampled down death by death. / He has become the first-born of the dead. / He has delivered us from the depths of hell, / and has granted the world great mercy!", group: 0, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone III", text: "On this day Thou didst rise from the tomb, O Merciful One, / leading us from the gates of death. / On this day Adam exults as Eve rejoices; / with the prophets and patriarchs they unceasingly praise / the divine majesty of Thy power!", group: 0, saints: [] },
		],
	}],
	[4, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone IV", text: "The mystery of all eternity, / unknown even by angels, / through you, O Theotokos, is revealed to those on earth: / God incarnate, by union without confusion. / He voluntarily accepted the cross for us, / by which He resurrected the first-created man, / saving our souls from death.", group: 0, saints: [] },
		{ title: "Troparion of the Sunday, Tone IV", text: "When the women disciples of the Lord learned from the angel / the joyous message of Thy resurrection, / they cast away the ancestral curse / and elatedly told the Apostles: / Death is overthrown! / Christ God is risen, / granting the world great mercy!", group: 0, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone IV", text: "My Savior and Redeemer as God rose from the tomb and delivered the earthborn from their chains. He has shattered the gates of hell, and as Master, He has risen on the third day!", group: 0, saints: [] },
		],
	}],
	[5, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone V", text: "Rejoice, O impassable gate of the Lord! / Rejoice, O wall and protection of those who run to you! / Rejoice, O unshakable refuge! / Rejoice, O Virgin Mother of your God and Creator! / Do not cease praying for those who praise you and worship your Son. (1x) Blessed be the name of the Lord, henceforth and forever more.", group: 0, saints: [] },
		{ title: "Troparion of the Sunday, Tone V", text: "Let us, the faithful, praise and worship the Word, / Co-eternal with the Father and the Spirit, / born for our salvation from the Virgin, / for He willed to be lifted up on the cross in the flesh, / to endure death / and to raise the dead by His glorious resurrection.", group: 0, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone V", text: "Thou didst descend into hell, O my Savior, / shattering its gates as almighty; / resurrecting the dead as Creator, / and destroying the sting of death. / Thou hast delivered Adam from the curse, O Lover of Man, / and we all cry to Thee: \"O Lord, save us!\"", group: 0, saints: [] },
		],
	}],
	[6, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone VI", text: "Thou Who didst call Thy mother blessed / came of Thine own will to the passion. / Shining on the cross, desiring to recall Adam, Thou didst say to the angels: / \"Rejoice with Me, for the lost coin has been found.\" / Thou Who hast ordered all things in wisdom, / O our God, glory to Thee! (1x) Blessed be the name of the Lord, henceforth and forever more.", group: 0, saints: [] },
		{ title: "Troparion of the Sunday, Tone VI", text: "The angelic powers were at Thy tomb; / the guards became as dead men. / Mary stood by Thy grave, / seeking Thy most pure Body. / Thou didst capture hell, / not being tempted by it. / Thou didst come to the Virgin, granting life. / O Lord, Who didst rise from the dead: glory to Thee!", group: 0, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone VI", text: "When Christ God, the Giver of Life, / raised all of the dead from the valleys of misery with His mighty hand, / He bestowed resurrection on the human race. / He is the Savior of all, the Resurrection, the Life, and the God of all.", group: 0, saints: [] },
		],
	}],
	[7, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone VII", text: "Since you are the treasure of our resurrection, / we put our hope in you, O all-praised one. / Lead us from the abyss of transgressions, / for you have saved those guilty of sin, / O evervirgin Mother of our salvation.", group: 0, saints: [] },
		{ title: "Troparion of the Sunday, Tone VII", text: "By Thy Cross, Thou didst destroy death! / To the thief, Thou didst open Paradise! / For the myrrhbearers, Thou didst change weeping into joy! / And Thou didst command Thy disciples, O Christ God, / to proclaim that Thou art risen, / granting the world great mercy!", group: 0, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone VII", text: "The dominion of death / can no longer hold men captive, / for Christ descended, shattering and destroying its powers! / Hell is bound, while the prophets rejoice and cry: /”The Savior has come to those in faith! / Enter, you faithful, into the Resurrection!", group: 0, saints: [] },
		],
	}],
	[8, {
		troparia: [
		{ title: "Hymn to the Theotokos, Tone VIII", text: "For our sake Thou wast born of the Virgin / and did endure crucifixion, O Good One, / destroying death by death. / Revealing the resurrection as God, / do not despise the work of Thy hand. / Reveal Thy love for man, O merciful One, / and accept the Theotokos praying for us, / and save Thy despairing people, O Savior.", group: 1, saints: [] },
		{ title: "Troparion of the Sunday, Tone VIII", text: "Thou didst descend from on high, O Merciful One! / Thou didst accept the three-day burial to free us from our sufferings! / O Lord, our Life and Resurrection: glory to Thee!", group: 1, saints: [] },
		],
		kontakia: [
		{ title: "Kontakion of the Sunday, Tone VIII", text: "By rising from the tomb, Thou didst raise the dead and resurrect Adam. / Eve exults in Thy Resurrection, / and the world celebrates Thy rising from the dead, O greatly Merciful One!", group: 1, saints: [] },
		],
	}],
]);

